const mri = require('./lib/index.js');

let passed = 0;
let failed = 0;

function test(name, fn) {
    try {
        fn();
        console.log(`✓ ${name}`);
        passed++;
    } catch (e) {
        console.log(`✗ ${name}: ${e.message}`);
        failed++;
    }
}

function assert(condition, msg) {
    if (!condition) throw new Error(msg || 'Assertion failed');
}

// Original issue: alias defaults should preserve string type
test('alias with string default preserves string type', () => {
    const res = mri(['-a', '01'], { alias: { arg: 'a' }, default: { arg: 'hello' } });
    assert(res.a === '01', `Expected "01", got ${res.a}`);
    assert(typeof res.a === 'string', `Expected string, got ${typeof res.a}`);
});

// Edge case: alias with boolean default
test('alias with boolean default preserves boolean type', () => {
    const res = mri(['--foo'], { alias: { bar: 'foo' }, default: { bar: false } });
    assert(res.foo === true, `Expected true, got ${res.foo}`);
});

// Edge case: multiple aliases with string default
test('multiple aliases with string default all get string type', () => {
    const res = mri(['-a', '007', '-b', '008'], { 
        alias: { arg: ['a', 'b'] }, 
        default: { arg: 'default' } 
    });
    assert(res.a === '007', `Expected "007", got ${res.a}`);
    assert(res.b === '008', `Expected "008", got ${res.b}`);
    assert(res.arg === '007', `Expected "007", got ${res.arg}`);
});

// Edge case: no value provided, should use default
test('alias uses default when no value provided', () => {
    const res = mri([], { alias: { arg: 'a' }, default: { arg: 'default' } });
    assert(res.arg === 'default', `Expected "default", got ${res.arg}`);
    assert(res.a === 'default', `Expected "default", got ${res.a}`);
});

// Edge case: string option without default should still work
test('string option without default still works', () => {
    const res = mri(['-s', '0001234'], { string: 's' });
    assert(res.s === '0001234', `Expected "0001234", got ${res.s}`);
    assert(typeof res.s === 'string', `Expected string, got ${typeof res.s}`);
});

// Edge case: default with number value
test('default with number value works correctly', () => {
    const res = mri([], { default: { count: 42 } });
    assert(res.count === 42, `Expected 42, got ${res.count}`);
    assert(typeof res.count === 'number', `Expected number, got ${typeof res.count}`);
});

// Edge case: alias with number default
test('alias with number default gets number type', () => {
    const res = mri(['-a', '5'], { alias: { arg: 'a' }, default: { arg: 10 } });
    assert(res.a === 5, `Expected 5, got ${res.a}`);
    assert(typeof res.a === 'number', `Expected number, got ${typeof res.a}`);
});

// Edge case: string alias on flag with no value
test('string alias with no value gets empty string', () => {
    const res = mri(['-a'], { alias: { arg: 'a' }, default: { arg: 'hello' } });
    // When -a is used without a value, it should be true (boolean)
    // But since it has a string default, let's see what happens
    assert(res.a === true || res.a === '', `Expected true or empty string, got ${res.a}`);
});

// Edge case: mixing string and boolean defaults with aliases
test('mixing string and boolean defaults with aliases', () => {
    const res = mri(['-s', '01', '-b'], { 
        alias: { str: 's', flag: 'b' }, 
        default: { str: 'default', flag: false } 
    });
    assert(res.s === '01', `Expected "01", got ${res.s}`);
    assert(res.b === true, `Expected true, got ${res.b}`);
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

const mri = require('./lib/index.js');

// Debug: default with number value
console.log('Test: default with number value');
const res1 = mri([], { default: { count: 42 } });
console.log('Result:', res1);

// Debug: alias with number default
console.log('\nTest: alias with number default');
const res2 = mri(['-a', '5'], { alias: { arg: 'a' }, default: { arg: 10 } });
console.log('Result:', res2);

// Debug: multiple aliases
console.log('\nTest: multiple aliases');
const res3 = mri(['-a', '007', '-b', '008'], { 
    alias: { arg: ['a', 'b'] }, 
    default: { arg: 'default' } 
});
console.log('Result:', res3);

